INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('BR-DISK', '^(?!.*\b((?<!HD[._ -]|HD)DVD|BDRip|MKV|XviD|WMV|d3g|(BD)?REMUX|^(?=.*1080p)(?=.*HEVC)|[xh][-_. ]?26[45]|German.*[DM]L|((?<=\d{4}).*German.*([DM]L)?)(?=.*\b(AVC|HEVC|VC[-_. ]?1|MVC|MPEG[-_. ]?2)\b))\b)(((?=.*\b(Blu[-_. ]?ray|BD|HD[-_. ]?DVD)\b)(?=.*\b(AVC|HEVC|VC[-_. ]?1|MVC|MPEG[-_. ]?2|BDMV|ISO)\b))|^((?=.*\b(((?=.*\b((.*_)?COMPLETE.*|Dis[ck])\b)(?=.*(Blu[-_. ]?ray|HD[-_. ]?DVD)))|3D[-_. ]?BD|BR[-_. ]?DISK|Full[-_. ]?Blu[-_. ]?ray|^((?=.*((BD|UHD)[-_. ]?(25|50|66|100|ISO)))))))).*', 'UpA3I7/2', NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('BluRay3D', '\b(BluRay3D)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Extras (Radarr)', '(?<=\b[12]\d{3}\b).*\b(Extras|Bonus|Extended[ ._-]Clip)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Extras (Sonarr)', '(?<=\bS\d+\b).*\b(Extras|Bonus|Extended[ ._-]Clip)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('GuyZo (2)', '\b(GuyZo|BR-GuyZo)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('RW', '\b(RW)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Regrade', '\b((Upscale)?Re-?graded?)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Sing-Along', '(?<=\b[12]\d{3}\b).*\b(Sing[-_. ]Along)\b', 'U9NMJU/1', NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('TheUpscaler', '\b(The[ ._-]?Upscaler)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Ukrainian In Title', '(?<!sub[^|\]]{0,6})(?:(?<![a-z])|(?<=\dx))(ukr|ukrainian)(?![a-z])(?![._-]?sub)|(?<![а-яіїєґa-z])укр', NULL, 'Ukrainian audio tag in the release title; subtitle-only tags are ignored.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Ukrainian Subs In Title', '(?<=sub[^|\]]{0,6})(?:(?<![a-z])|(?<=\dx))(ukr|ukrainian)(?![a-z])|(?<![a-z])(ukr|ukrainian)[._-]?sub', NULL, 'Ukrainian subtitle tag in the release title, such as sub Ukr, UKRsub or [UKR-sub].');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Upscaled (Radarr)', '(?<=\b[12]\d{3}\b).*\b(AI[ ._-]?(Enhanced?|Remaster(ed)?)|UPS(UHD)?|Upscaled?([ ._-]?UHD)?|UpRez)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Upscaled (Sonarr)', '(?<=\b\d{3,4}p\b).*\b(AI[ ._-]?(Enhanced?|Remaster(ed)?)|UPS(UHD)?|Upscaled?([ ._-]?UHD)?|UpRez)\b', NULL, NULL);
